import{_ as d,a0 as n,w as l,s as i,ao as p,I as s,x as t,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"檢查linux中硬盤損壞的扇區和區塊 | LCTT x X-CMD","titleTemplate":false,"description":"檢查linux中硬盤損壞的扇區和區塊 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"檢查linux中硬盤損壞的扇區和區塊 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"檢查linux中硬盤損壞的扇區和區塊 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux","title":"檢查linux中硬盤損壞的扇區和區塊","tag":"201408","desc":""},"relativePath":"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux.md","filePath":"[post].md"}'),u={name:"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux.md"};function b(f,e,k,x,c,m){const a=n("Link");return l(),i("div",null,[e[13]||(e[13]=p(`<h1 id="檢查linux中硬盤損壞的扇區和區塊" tabindex="-1">檢查linux中硬盤損壞的扇區和區塊 <a class="header-anchor" href="#檢查linux中硬盤損壞的扇區和區塊" aria-label="Permalink to “檢查linux中硬盤損壞的扇區和區塊”">​</a></h1><p><strong>badblocks</strong>是linux及其類似的操作系統中，掃描檢查硬盤和外部設備損壞扇區的命令工具。損壞的扇區或者損壞的區塊是硬盤中因為永久損壞或者是操作系統不能讀取的空間。</p><p>Badblocks命令可以探測硬盤中所有損壞的扇區或者區塊並將結果保存在一個文本文檔中，這樣，我們就可以使用<strong>e2fsck</strong>命令來配置操作系統不在這些損壞的扇區中存儲數據。</p><h3 id="步驟-1-使用fdisk命令識別硬盤信息" tabindex="-1">步驟:1 使用fdisk命令識別硬盤信息 <a class="header-anchor" href="#步驟-1-使用fdisk命令識別硬盤信息" aria-label="Permalink to “步驟:1 使用fdisk命令識別硬盤信息”">​</a></h3><pre><code># sudo fdisk -l 
</code></pre><h3 id="步驟-2-掃描硬盤的損壞扇區或區塊" tabindex="-1">步驟:2 掃描硬盤的損壞扇區或區塊 <a class="header-anchor" href="#步驟-2-掃描硬盤的損壞扇區或區塊" aria-label="Permalink to “步驟:2  掃描硬盤的損壞扇區或區塊”">​</a></h3><pre><code># sudo badblocks -v /dev/sdb &gt; /tmp/bad-blocks.txt
</code></pre><p>只需將“/dev/sdb”替換為自己機器的硬盤/分區。執行完成上述命令後，一個名為“bad-blocks”文本文檔將會在/tmp下創建，它將包含所有的損壞區塊。</p><p>例如：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/08/badblocks.png" alt=""></p><h3 id="步驟-3-提示-操作系統不要使用損壞區塊存儲" tabindex="-1">步驟:3 提示 操作系統不要使用損壞區塊存儲 <a class="header-anchor" href="#步驟-3-提示-操作系統不要使用損壞區塊存儲" aria-label="Permalink to “步驟:3 提示 操作系統不要使用損壞區塊存儲”">​</a></h3><p>掃描完成後，如果損壞區塊被發現了，然後通過e2fsck命令使用“bad-blocks.txt”，強迫操作系統不使用這些損壞的區塊存儲數據。</p><pre><code># sudo e2fsck -l /tmp/bad-blocks.txt  /dev/sdb
</code></pre><p>注意：在運行e2fsck命令前，請保證設備沒有被掛載。</p><p>關於badblocks和e2fsck命令的更多幫助，請參考下列man頁面</p><pre><code># man badblocks
# man e2fsck  
</code></pre><hr>`,17)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"http://www.linuxtechi.com/check-hard-drive-for-bad-sector-linux/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.linuxtechi.com/check-hard-drive-for-bad-sector-linux/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),r(a,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),r(a,{href:"http://www.vicyu.net"},{default:o(()=>[...e[3]||(e[3]=[t("Vic___",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),r(a,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[4]||(e[4]=[t("Caroline",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const w=d(u,[["render",b]]);export{C as __pageData,w as default};
